"use client";
import { motion } from "motion/react";
import { useId, useMemo, useState } from "react";
import { useHydratedReducedMotion } from "../../hooks/use-hydrated-reduced-motion";
import {
  Cell,
  PolarAngleAxis,
  RadialBar,
  RadialBarChart,
  ResponsiveContainer,
  Tooltip,
} from "recharts";
import { ChartLegend } from "./chart-legend";
import { HalfRingPlot } from "./half-ring-plot";
import { cx } from "../../utils/cx";
import { formatNumber } from "./chart-card";
import { RADIAL_DEMO_RANGES } from "./chart-demo-data";
import {
  AnimatedNumber,
  type ChartCommonProps,
  ChartFrame,
  type ChartRange,
  ink,
  PeriodSelect,
  StatTiles,
  safeRatio,
  sum,
  useChartRange,
} from "./pro-chart";
export interface RadialItem {
  label: string;
  value: number;
  color?: string;
}
export interface RadialChartRange extends ChartRange {
  data: RadialItem[];
  max?: number;
}
export interface RadialChartCardProps extends ChartCommonProps {
  data?: RadialItem[];
  ranges?: RadialChartRange[];
  max?: number;
  variant?: "rings" | "labels" | "grid" | "gauge" | "solid" | "stacked";
  tiles?: boolean;
}
export const RADIAL_DATA: RadialItem[] = RADIAL_DEMO_RANGES[0]!.data;
const RANGES: RadialChartRange[] = RADIAL_DEMO_RANGES;

export function RadialChartCard({
  data,
  ranges: supplied,
  title = "Visitors",
  variant = "rings",
  tiles = false,
  max,
  ...props
}: RadialChartCardProps = {}) {
  const ranges = supplied ?? (data ? undefined : RANGES),
    period = useChartRange(ranges, props.defaultRange, props.onRangeChange),
    items = period.current?.data ?? data ?? RADIAL_DATA,
    [active, setActive] = useState<number | null>(null),
    reduced = useHydratedReducedMotion(),
    id = useId(),
    total = sum(items.map((d) => d.value)),
    requestedCeiling =
      period.current?.max ?? max ?? Math.ceil(Math.max(1, ...items.map((d) => d.value)) * 1.1),
    ceiling = Number.isFinite(requestedCeiling) && requestedCeiling > 0 ? requestedCeiling : 1,
    format = props.format ?? formatNumber,
    single = variant === "gauge" || variant === "solid",
    stacked = variant === "stacked",
    primary = items[active ?? 0],
    percent = safeRatio(primary?.value ?? 0, stacked ? total : requestedCeiling) * 100;
  const plotItems = useMemo(
    () =>
      items.map((item) => ({
        ...item,
        value: safeRatio(item.value, requestedCeiling) * ceiling,
      })),
    [items, requestedCeiling, ceiling],
  );
  let offset = 0;
  return (
    <ChartFrame
      title={active == null ? title : (items[active]?.label ?? title)}
      value={
        active == null
          ? (period.current?.headline ?? props.headline ?? total)
          : (items[active]?.value ?? 0)
      }
      format={format}
      delta={active == null ? (period.current?.delta ?? props.delta) : undefined}
      animateNumber
      pulseKey={active}
      className={cx(stacked && "h-[329px] max-sm:h-auto max-sm:min-h-[329px]", props.className)}
      action={
        <PeriodSelect
          ranges={ranges}
          selected={period.id}
          onChange={(id) => {
            setActive(null);
            period.select(id);
          }}
          label={period.current?.label ?? props.range ?? "Last 7 days"}
        />
      }
      footer={
        tiles ? (
          <StatTiles
            items={items.map((s, i) => ({
              label: s.label,
              value: format(s.value),
              color: s.color ?? ink(i),
              activeColor: s.color ?? ink(i).replace(")", "-active)"),
            }))}
            responsive
            fillLastOdd
            balanceLastRow
            focusable={false}
            inactiveOpacity={0.4}
            active={active}
            onHover={setActive}
          />
        ) : (
          stacked && (
            <ChartLegend
              items={items.map((s, i) => ({
                label: s.label,
                value: format(s.value),
                color: s.color ?? ink(i),
              }))}
            />
          )
        )
      }
    >
      <div
        className={cx(
          "relative w-full",
          stacked ? "min-h-0 flex-1 max-sm:min-h-[180px]" : "h-[231px]",
        )}
      >
        {stacked ? (
          <>
            <HalfRingPlot
              items={items.map((item, i) => ({ ...item, color: item.color ?? ink(i) }))}
              active={active}
              onInspect={setActive}
            />
            <div className="pointer-events-none absolute inset-x-0 top-0 h-[78%]">
              <div className="absolute inset-0 flex flex-col items-center justify-end">
                <span className="animate-number-fade text-display-4-medium text-text-primary tabular-nums">
                  <AnimatedNumber
                    value={percent}
                    format={(n) => `${Math.round(n)}%`}
                    duration={320}
                  />
                </span>
                <span className="animate-number-fade -mt-1 max-w-[120px] truncate text-caption-1-medium text-text-tertiary">
                  {primary?.label}
                </span>
              </div>
            </div>
          </>
        ) : variant === "rings" ? (
          <ResponsiveContainer width="100%" height="100%">
            <RadialBarChart
              data={plotItems}
              cx="50%"
              cy="50%"
              innerRadius={44}
              outerRadius={106}
              startAngle={90}
              endAngle={-270}
              barCategoryGap="22%"
            >
              <PolarAngleAxis type="number" domain={[0, ceiling]} tick={false} />
              <Tooltip content={() => null} cursor={false} />
              <RadialBar
                dataKey="value"
                cornerRadius={9}
                background={{ fill: "var(--color-chart-track)" }}
                isAnimationActive={!reduced}
                animationDuration={450}
                animationEasing="ease"
                onMouseEnter={(_, index) => setActive(index)}
                onMouseLeave={() => setActive(null)}
              >
                {items.map((item, index) => (
                  <Cell
                    key={item.label}
                    fill={
                      active === index
                        ? (item.color ?? ink(index).replace(")", "-active)"))
                        : (item.color ?? ink(index))
                    }
                    opacity={active != null && active !== index ? 0.25 : 1}
                    className="transition-[fill,opacity] duration-200 ease-out"
                  />
                ))}
              </RadialBar>
            </RadialBarChart>
          </ResponsiveContainer>
        ) : (
          <svg
            viewBox="0 0 260 231"
            className="h-full w-full"
            role="img"
            aria-label={items.map((s) => `${s.label}: ${format(s.value)}`).join(", ")}
          >
            {variant === "solid" && (
              <circle cx={130} cy={115.5} r={102} fill="var(--color-background-inner-default)" />
            )}
            {variant === "grid" &&
              [25, 50, 75, 100].map((r) => (
                <circle
                  key={r}
                  cx={130}
                  cy={115.5}
                  r={r}
                  fill="none"
                  stroke="var(--color-chart-track)"
                  strokeDasharray="3 3"
                />
              ))}
            {(single ? items.slice(0, 1) : items).map((item, i) => {
              const r = single ? 82 : stacked ? 88 : 50 + i * (50 / Math.max(1, items.length - 1)),
                width = single ? (variant === "solid" ? 24 : 12) : stacked ? 24 : 7,
                progress =
                  safeRatio(item.value, stacked ? total : requestedCeiling) * (stacked ? 50 : 100),
                start = offset;
              offset += progress;
              const color = item.color ?? ink(i);
              return (
                <g
                  key={`${period.id}-${item.label}`}
                  transform={`rotate(${stacked ? -180 : -90} 130 115.5)`}
                  onMouseEnter={() => setActive(i)}
                  onMouseLeave={() => setActive(null)}
                  opacity={active != null && active !== i ? 0.25 : 1}
                  className="transition-opacity duration-200 motion-reduce:transition-none"
                >
                  {variant !== "grid" && !stacked && (
                    <circle
                      cx={130}
                      cy={115.5}
                      r={r}
                      fill="none"
                      stroke="var(--color-chart-track)"
                      strokeWidth={width}
                    />
                  )}
                  <motion.circle
                    key={reduced ? "reduced" : "animated"}
                    id={`${id}-${i}`}
                    cx={130}
                    cy={115.5}
                    r={r}
                    pathLength={100}
                    fill="none"
                    stroke={color}
                    strokeWidth={width}
                    strokeLinecap="round"
                    strokeDashoffset={stacked ? -start : 0}
                    initial={reduced ? false : { strokeDasharray: "0 100" }}
                    animate={{
                      strokeDasharray: `${Math.max(0, progress - (stacked ? 1 : 0))} 100`,
                    }}
                    transition={{
                      duration: reduced ? 0 : 0.7,
                      ease: "easeOut",
                    }}
                  />
                  {variant === "labels" && (
                    <text fill="var(--color-text-primary)" fontSize={10} dy={3}>
                      <textPath href={`#${id}-${i}`} startOffset="3%">
                        {item.label}
                      </textPath>
                    </text>
                  )}
                </g>
              );
            })}
          </svg>
        )}
        {single && (
          <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center">
            <span className="text-title-1-medium text-text-primary">
              <AnimatedNumber value={percent} />%
            </span>
            <span className="text-body-2-regular text-text-secondary">
              {stacked ? primary?.label : "of goal"}
            </span>
          </div>
        )}
      </div>
    </ChartFrame>
  );
}
